--   showcase               production:oil_batch_balance:read

begin;

insert into iam.permission_master (permission_code, permission_name, module_name, status, created_by, updated_by)
select v.code, v.code, split_part(v.code, ':', 1), 'ACTIVE', 'release-grant', 'release-grant'
  from (values ('production:oil_batch_balance:read'), ('production:oil_batch_remnant:write'), ('production:oil_batch:write_off'), ('production:floor_mix:reveal_name'), ('masterdata:material_import:write')) as v(code)
 where not exists (select 1 from iam.permission_master p where p.permission_code = v.code);

insert into iam.role_permission_mapping (role_id, permission_id, status, created_by, updated_by)
select r.role_id, p.permission_id, 'ACTIVE', 'release-grant', 'release-grant'
  from (values
    ('owner', 'production:oil_batch_balance:read'),
    ('owner', 'production:oil_batch_remnant:write'),
    ('owner', 'production:oil_batch:write_off'),
    ('owner', 'production:floor_mix:reveal_name'),
    ('owner', 'masterdata:material_import:write'),
    ('admin', 'production:oil_batch_balance:read'),
    ('admin', 'production:oil_batch_remnant:write'),
    ('admin', 'production:oil_batch:write_off'),
    ('procurement', 'masterdata:material_import:write'),
    ('qc', 'production:oil_batch_balance:read'),
    ('compounding', 'production:oil_batch_balance:read'),
    ('compounding', 'production:oil_batch_remnant:write'),
    ('production', 'production:oil_batch_balance:read'),
    ('production', 'production:oil_batch_remnant:write'),
    ('production', 'production:oil_batch:write_off'),
    ('filling', 'production:oil_batch_balance:read'),
    ('packaging', 'production:oil_batch_balance:read'),
    ('packaging', 'production:oil_batch_remnant:write'),
    ('mixer', 'production:floor_mix:reveal_name'),
    ('packing', 'production:oil_batch_balance:read'),
    ('showcase', 'production:oil_batch_balance:read')
  ) as g(role_code, permission_code)
  join iam.role_master r on r.role_code = g.role_code
  join iam.permission_master p on p.permission_code = g.permission_code
 where not exists (select 1 from iam.role_permission_mapping m where m.role_id = r.role_id and m.permission_id = p.permission_id);

commit;
